     1→/**
     2→ * AgentPing Component
     3→ * 
     4→ * Rich audit results display with actionable notifications.
     5→ * Types: status, question, approval, alert, audit
     6→ */
     7→
     8→import { useState } from 'react';
     9→import { motion, AnimatePresence } from 'framer-motion';
    10→
    11→export type PingType = 'status' | 'question' | 'approval' | 'alert' | 'audit';
    12→export type PingPriority = 'low' | 'medium' | 'high' | 'critical';
    13→
    14→export interface PingAction {
    15→  label: string;
    16→  value: string;
    17→  variant?: 'primary' | 'secondary' | 'danger';
    18→  icon?: string;
    19→}
    20→
    21→export interface AuditFinding {
    22→  severity: 'info' | 'warning' | 'error' | 'critical';
    23→  category: string;
    24→  message: string;
    25→  location?: string;
    26→  suggestion?: string;
    27→}
    28→
    29→export interface AgentPingData {
    30→  id: string;
    31→  source: string;  // Agent name
    32→  type: PingType;
    33→  priority: PingPriority;
    34→  title: string;
    35→  content: string;
    36→  timestamp: Date;
    37→  actions?: PingAction[];
    38→  
    39→  // Audit-specific
    40→  auditResults?: {
    41→    passed: number;
    42→    failed: number;
    43→    warnings: number;
    44→    findings: AuditFinding[];
    45→  };
    46→  
    47→  // Status
    48→  read?: boolean;
    49→  resolved?: boolean;
    50→  resolvedAt?: Date;
    51→  resolvedBy?: string;
    52→}
    53→
    54→const PING_ICONS: Record<PingType, string> = {
    55→  status: '📊',
    56→  question: '❓',
    57→  approval: '✅',
    58→  alert: '⚠️',
    59→  audit: '🔍',
    60→};
    61→
    62→const PRIORITY_COLORS: Record<PingPriority, string> = {
    63→  low: 'bg-gray-500/20 border-gray-500/30',
    64→  medium: 'bg-blue-500/20 border-blue-500/30',
    65→  high: 'bg-amber-500/20 border-amber-500/30',
    66→  critical: 'bg-red-500/20 border-red-500/30 animate-pulse',
    67→};
    68→
    69→const SEVERITY_STYLES: Record<AuditFinding['severity'], string> = {
    70→  info: 'text-blue-400 bg-blue-500/10',
    71→  warning: 'text-amber-400 bg-amber-500/10',
    72→  error: 'text-red-400 bg-red-500/10',
    73→  critical: 'text-red-500 bg-red-500/20 font-bold',
    74→};
    75→
    76→interface AgentPingProps {
    77→  ping: AgentPingData;
    78→  onAction?: (pingId: string, action: string) => void;
    79→  onDismiss?: (pingId: string) => void;
    80→  expanded?: boolean;
    81→}
    82→
    83→export function AgentPing({ ping, onAction, onDismiss, expanded: initialExpanded }: AgentPingProps) {
    84→  const [expanded, setExpanded] = useState(initialExpanded ?? false);
    85→  
    86→  const timeAgo = getTimeAgo(ping.timestamp);
    87→  const isAudit = ping.type === 'audit' && ping.auditResults;
    88→  
    89→  return (
    90→    <motion.div
    91→      initial={{ opacity: 0, y: -20 }}
    92→      animate={{ opacity: 1, y: 0 }}
    93→      exit={{ opacity: 0, x: 100 }}
    94→      className={`
    95→        rounded-xl border backdrop-blur-md p-4
    96→        ${PRIORITY_COLORS[ping.priority]}
    97→        ${ping.resolved ? 'opacity-60' : ''}
    98→      `}
    99→    >
   100→      {/* Header */}
   101→      <div className="flex items-start justify-between gap-3">
   102→        <div className="flex items-center gap-3">
   103→          <span className="text-2xl">{PING_ICONS[ping.type]}</span>
   104→          <div>
   105→            <div className="flex items-center gap-2">
   106→              <span className="font-mono text-sm text-cyan-400">{ping.source}</span>
   107→              <span className="text-xs text-gray-500">{timeAgo}</span>
   108→            </div>
   109→            <h3 className="font-semibold text-white">{ping.title}</h3>
   110→          </div>
   111→        </div>
   112→        
   113→        {onDismiss && (
   114→          <button
   115→            onClick={() => onDismiss(ping.id)}
   116→            className="text-gray-500 hover:text-white transition-colors"
   117→          >
   118→            ✕
   119→          </button>
   120→        )}
   121→      </div>
   122→      
   123→      {/* Content */}
   124→      <p className="mt-2 text-gray-300 text-sm">{ping.content}</p>
   125→      
   126→      {/* Audit Results */}
   127→      {isAudit && (
   128→        <div className="mt-4">
   129→          {/* Summary Bar */}
   130→          <div className="flex gap-4 text-sm mb-3">
   131→            <span className="text-green-400">
   132→              ✓ {ping.auditResults!.passed} passed
   133→            </span>
   134→            <span className="text-red-400">
   135→              ✗ {ping.auditResults!.failed} failed
   136→            </span>
   137→            <span className="text-amber-400">
   138→              ⚠ {ping.auditResults!.warnings} warnings
   139→            </span>
   140→          </div>
   141→          
   142→          {/* Progress Bar */}
   143→          <div className="h-2 bg-gray-800 rounded-full overflow-hidden flex">
   144→            <div 
   145→              className="bg-green-500 h-full"
   146→              style={{ 
   147→                width: `${(ping.auditResults!.passed / (ping.auditResults!.passed + ping.auditResults!.failed + ping.auditResults!.warnings)) * 100}%` 
   148→              }}
   149→            />
   150→            <div 
   151→              className="bg-red-500 h-full"
   152→              style={{ 
   153→                width: `${(ping.auditResults!.failed / (ping.auditResults!.passed + ping.auditResults!.failed + ping.auditResults!.warnings)) * 100}%` 
   154→              }}
   155→            />
   156→            <div 
   157→              className="bg-amber-500 h-full"
   158→              style={{ 
   159→                width: `${(ping.auditResults!.warnings / (ping.auditResults!.passed + ping.auditResults!.failed + ping.auditResults!.warnings)) * 100}%` 
   160→              }}
   161→            />
   162→          </div>
   163→          
   164→          {/* Expand/Collapse Findings */}
   165→          <button
   166→            onClick={() => setExpanded(!expanded)}
   167→            className="mt-3 text-sm text-cyan-400 hover:text-cyan-300 flex items-center gap-1"
   168→          >
   169→            {expanded ? '▼' : '▶'} {ping.auditResults!.findings.length} findings
   170→          </button>
   171→          
   172→          {/* Findings List */}
   173→          <AnimatePresence>
   174→            {expanded && (
   175→              <motion.div
   176→                initial={{ height: 0, opacity: 0 }}
   177→                animate={{ height: 'auto', opacity: 1 }}
   178→                exit={{ height: 0, opacity: 0 }}
   179→                className="overflow-hidden"
   180→              >
   181→                <div className="mt-3 space-y-2 max-h-64 overflow-y-auto">
   182→                  {ping.auditResults!.findings.map((finding, i) => (
   183→                    <div
   184→                      key={i}
   185→                      className={`
   186→                        p-3 rounded-lg text-sm
   187→                        ${SEVERITY_STYLES[finding.severity]}
   188→                      `}
   189→                    >
   190→                      <div className="flex justify-between items-start">
   191→                        <span className="font-medium">{finding.category}</span>
   192→                        <span className="text-xs opacity-70">{finding.severity}</span>
   193→                      </div>
   194→                      <p className="mt-1">{finding.message}</p>
   195→                      {finding.location && (
   196→                        <p className="mt-1 text-xs opacity-70 font-mono">
   197→                          📍 {finding.location}
   198→                        </p>
   199→                      )}
   200→                      {finding.suggestion && (
   201→                        <p className="mt-2 text-xs italic opacity-80">
   202→                          💡 {finding.suggestion}
   203→                        </p>
   204→                      )}
   205→                    </div>
   206→                  ))}
   207→                </div>
   208→              </motion.div>
   209→            )}
   210→          </AnimatePresence>
   211→        </div>
   212→      )}
   213→      
   214→      {/* Actions */}
   215→      {ping.actions && ping.actions.length > 0 && !ping.resolved && (
   216→        <div className="mt-4 flex gap-2 flex-wrap">
   217→          {ping.actions.map((action) => (
   218→            <button
   219→              key={action.value}
   220→              onClick={() => onAction?.(ping.id, action.value)}
   221→              className={`
   222→                px-4 py-2 rounded-lg text-sm font-medium transition-all
   223→                ${action.variant === 'primary' 
   224→                  ? 'bg-cyan-500 hover:bg-cyan-400 text-black' 
   225→                  : action.variant === 'danger'
   226→                  ? 'bg-red-500/20 hover:bg-red-500/30 text-red-400 border border-red-500/30'
   227→                  : 'bg-gray-700 hover:bg-gray-600 text-white'}
   228→              `}
   229→            >
   230→              {action.icon && <span className="mr-1">{action.icon}</span>}
   231→              {action.label}
   232→            </button>
   233→          ))}
   234→        </div>
   235→      )}
   236→      
   237→      {/* Resolved Badge */}
   238→      {ping.resolved && (
   239→        <div className="mt-3 text-xs text-gray-500">
   240→          ✓ Resolved {ping.resolvedAt ? getTimeAgo(ping.resolvedAt) : ''} 
   241→          {ping.resolvedBy && ` by ${ping.resolvedBy}`}
   242→        </div>
   243→      )}
   244→    </motion.div>
   245→  );
   246→}
   247→
   248→// Helper
   249→function getTimeAgo(date: Date): string {
   250→  const seconds = Math.floor((Date.now() - new Date(date).getTime()) / 1000);
   251→  
   252→  if (seconds < 60) return 'just now';
   253→  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
   254→  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
   255→  return `${Math.floor(seconds / 86400)}d ago`;
   256→}
   257→
   258→// Panel Component for Dashboard
   259→interface AgentPingPanelProps {
   260→  pings: AgentPingData[];
   261→  onAction?: (pingId: string, action: string) => void;
   262→  onDismiss?: (pingId: string) => void;
   263→  maxVisible?: number;
   264→}
   265→
   266→export function AgentPingPanel({ pings, onAction, onDismiss, maxVisible = 5 }: AgentPingPanelProps) {
   267→  const [filter, setFilter] = useState<PingType | 'all'>('all');
   268→  
   269→  const filteredPings = pings
   270→    .filter(p => filter === 'all' || p.type === filter)
   271→    .slice(0, maxVisible);
   272→  
   273→  const unreadCount = pings.filter(p => !p.read).length;
   274→  
   275→  return (
   276→    <div className="bg-gray-900/50 backdrop-blur-md rounded-2xl border border-gray-800 p-4">
   277→      {/* Header */}
   278→      <div className="flex items-center justify-between mb-4">
   279→        <h2 className="text-lg font-semibold text-white flex items-center gap-2">
   280→          🔔 Agent Pings
   281→          {unreadCount > 0 && (
   282→            <span className="bg-cyan-500 text-black text-xs px-2 py-0.5 rounded-full">
   283→              {unreadCount} new
   284→            </span>
   285→          )}
   286→        </h2>
   287→        
   288→        {/* Filter */}
   289→        <select
   290→          value={filter}
   291→          onChange={(e) => setFilter(e.target.value as PingType | 'all')}
   292→          className="bg-gray-800 border border-gray-700 rounded-lg px-2 py-1 text-sm text-gray-300"
   293→        >
   294→          <option value="all">All</option>
   295→          <option value="audit">🔍 Audits</option>
   296→          <option value="approval">✅ Approvals</option>
   297→          <option value="alert">⚠️ Alerts</option>
   298→          <option value="question">❓ Questions</option>
   299→          <option value="status">📊 Status</option>
   300→        </select>
   301→      </div>
   302→      
   303→      {/* Pings List */}
   304→      <div className="space-y-3">
   305→        <AnimatePresence>
   306→          {filteredPings.length === 0 ? (
   307→            <p className="text-gray-500 text-center py-8">No pings</p>
   308→          ) : (
   309→            filteredPings.map((ping) => (
   310→              <AgentPing
   311→                key={ping.id}
   312→                ping={ping}
   313→                onAction={onAction}
   314→                onDismiss={onDismiss}
   315→              />
   316→            ))
   317→          )}
   318→        </AnimatePresence>
   319→      </div>
   320→      
   321→      {/* Show More */}
   322→      {pings.length > maxVisible && (
   323→        <button className="mt-4 w-full text-center text-sm text-cyan-400 hover:text-cyan-300">
   324→          View all {pings.length} pings →
   325→        </button>
   326→      )}
   327→    </div>
   328→  );
   329→}
   330→
   331→export default AgentPing;
   332→

