import { useAgentPing } from './hooks/useAgentPing'
import { CanvasRenderer } from './components/CanvasRenderer'
import { ConnectionStatus } from './components/ConnectionStatus'

function timeAgo(iso: string): string {
  const seconds = Math.floor((Date.now() - new Date(iso).getTime()) / 1000)
  if (seconds < 60) return `${seconds}s ago`
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(hours / 24)
  return `${days}d ago`
}

const priorityColor: Record<string, string> = {
  critical: 'var(--danger)',
  high: 'var(--warning)',
  medium: 'var(--primary)',
  low: 'var(--text-muted)',
}

export default function App() {
  const { pings, status, respond } = useAgentPing()

  const sorted = [...pings].sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  )

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      {/* Header */}
      <header className="fixed top-0 left-0 right-0 z-50 glass-panel px-6 py-3 flex items-center justify-between">
        <span className="font-mono text-[var(--primary)] text-lg font-semibold">
          Lev Canvas
        </span>
        <ConnectionStatus status={status} />
      </header>

      {/* Main */}
      <main className="pt-16 px-6 py-6 max-w-7xl mx-auto space-y-6">
        {sorted.length === 0 ? (
          <div className="flex items-center justify-center min-h-[60vh]">
            <p className="text-[var(--text-muted)] font-mono text-sm animate-pulse-glow">
              Waiting for canvas interactions...
            </p>
          </div>
        ) : (
          sorted.map((ping) => (
            <div
              key={ping.id}
              className="glass-panel rounded-[var(--radius-lg)] p-5 space-y-4"
            >
              {/* Card header */}
              <div className="flex items-start justify-between gap-4">
                <div className="space-y-1">
                  <h2 className="font-semibold text-[var(--text-primary)]">
                    {ping.title}
                  </h2>
                  <p className="text-sm text-[var(--text-secondary)]">
                    {ping.message}
                  </p>
                </div>
                <div className="flex items-center gap-3 shrink-0">
                  <span
                    className="text-xs font-mono px-2 py-0.5 rounded-full"
                    style={{
                      color: priorityColor[ping.priority] ?? 'var(--text-muted)',
                      border: `1px solid ${priorityColor[ping.priority] ?? 'var(--text-muted)'}`,
                    }}
                  >
                    {ping.priority}
                  </span>
                  <span className="text-xs text-[var(--text-muted)] font-mono">
                    {timeAgo(ping.timestamp)}
                  </span>
                </div>
              </div>

              {/* Canvas render area */}
              <CanvasRenderer
                componentType={ping.payload?.componentType}
                props={ping.payload?.props}
                onRespond={(data) => respond(ping.id, data)}
              />
            </div>
          ))
        )}
      </main>
    </div>
  )
}

