import { useState, useEffect, useRef, useCallback } from 'react';
import { z } from 'zod';

// ---------------------------------------------------------------------------
// Schema & types
// ---------------------------------------------------------------------------

const CanvasInteractionPayloadSchema = z.object({
  type: z.literal('canvas_interaction'),
  action: z.enum(['render', 'selection']),
  componentType: z.string().optional(),
  componentName: z.string().optional(),
  props: z.record(z.string(), z.unknown()).optional(),
  instruction: z.string().optional(),
  selectionType: z.string().optional(),
});

export interface CanvasPing {
  id: string;
  type: string;
  title: string;
  message: string;
  priority: 'low' | 'medium' | 'high' | 'critical';
  status: 'pending' | 'responded' | 'expired' | 'dismissed' | 'cancelled';
  payload: {
    type: 'canvas_interaction';
    action: 'render' | 'selection';
    componentType?: string;
    componentName?: string;
    props?: Record<string, unknown>;
    instruction?: string;
    selectionType?: string;
  };
  createdAt: string;
  expiresAt?: string;
}

type PingEvent =
  | 'ping:created'
  | 'ping:responded'
  | 'ping:expired'
  | 'ping:dismissed'
  | 'ping:cancelled';

interface WsMessage {
  event: PingEvent;
  data: Record<string, unknown>;
}

const STATUS_FROM_EVENT: Record<PingEvent, CanvasPing['status']> = {
  'ping:created': 'pending',
  'ping:responded': 'responded',
  'ping:expired': 'expired',
  'ping:dismissed': 'dismissed',
  'ping:cancelled': 'cancelled',
};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const WS_URL = 'ws://localhost:7890/api/v1/ws';
const API_BASE = '/api/v1/pings';
const INITIAL_BACKOFF_MS = 1_000;
const MAX_BACKOFF_MS = 30_000;

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

export function useAgentPing() {
  const [pings, setPings] = useState<CanvasPing[]>([]);
  const [connected, setConnected] = useState(false);

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const backoff = useRef(INITIAL_BACKOFF_MS);
  const unmounted = useRef(false);

  // ---- REST helpers -------------------------------------------------------

  const fetchPending = useCallback(async () => {
    try {
      const res = await fetch(
        `${API_BASE}?status=pending&type=canvas_interaction`,
      );
      if (!res.ok) return;
      const data: CanvasPing[] = await res.json();
      setPings(data.sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
    } catch {
      // silently ignore fetch errors; will retry on next connect
    }
  }, []);

  const respond = useCallback(
    async (pingId: string, data: Record<string, unknown>): Promise<void> => {
      const res = await fetch(`${API_BASE}/${pingId}/respond`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      if (!res.ok) {
        throw new Error(`Respond failed: ${res.status}`);
      }
    },
    [],
  );

  // ---- WebSocket lifecycle ------------------------------------------------

  const connect = useCallback(() => {
    if (unmounted.current) return;

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => {
      if (unmounted.current) return;
      setConnected(true);
      backoff.current = INITIAL_BACKOFF_MS;
      fetchPending();
    };

    ws.onclose = () => {
      if (unmounted.current) return;
      setConnected(false);
      scheduleReconnect();
    };

    ws.onerror = () => {
      // onclose will fire after onerror; reconnect handled there
      ws.close();
    };

    ws.onmessage = (event: MessageEvent) => {
      if (unmounted.current) return;

      let msg: WsMessage;
      try {
        msg = JSON.parse(event.data as string) as WsMessage;
      } catch {
        return;
      }

      const ping = msg.data as unknown as CanvasPing;

      if (msg.event === 'ping:created') {
        const parsed = CanvasInteractionPayloadSchema.safeParse(ping.payload);
        if (!parsed.success) return;

        setPings((prev) => [ping, ...prev]);
        return;
      }

      // Status-update events
      const newStatus = STATUS_FROM_EVENT[msg.event];
      if (!newStatus) return;

      setPings((prev) =>
        prev.map((p) =>
          p.id === ping.id ? { ...p, status: newStatus } : p,
        ),
      );
    };
  }, [fetchPending]);

  const scheduleReconnect = useCallback(() => {
    if (unmounted.current) return;

    reconnectTimer.current = setTimeout(() => {
      if (unmounted.current) return;
      connect();
    }, backoff.current);

    backoff.current = Math.min(backoff.current * 2, MAX_BACKOFF_MS);
  }, [connect]);

  // ---- Mount / unmount ----------------------------------------------------

  useEffect(() => {
    unmounted.current = false;
    connect();

    return () => {
      unmounted.current = true;
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  return { pings, connected, respond, fetchPending } as const;
}

