@import "tailwindcss";

:root,
:root[data-theme="dark"] {
  --bg-primary: #050505;
  --bg-secondary: #0a0a0a;
  --bg-tertiary: #121212;
  --bg-elevated: #1a1a1a;
  --text-primary: #fafafa;
  --text-secondary: #a1a1aa;
  --text-muted: #52525b;
  --primary: #00e5ff;
  --primary-dim: #00b8d4;
  --success: #00ff9d;
  --warning: #ffb800;
  --danger: #ff2a6d;
  --glass-bg: rgba(10, 10, 10, 0.7);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-highlight: rgba(255, 255, 255, 0.04);
  --glow-primary: 0 0 20px rgba(0, 229, 255, 0.15);
  --glow-success: 0 0 20px rgba(0, 255, 157, 0.15);
  --glow-danger: 0 0 20px rgba(255, 42, 109, 0.15);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', monospace;
  --radius-sm: 0.375rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
}

/* Glass panel utility */
.glass-panel {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

/* Glow effects */
.glow-primary { box-shadow: var(--glow-primary); }
.glow-success { box-shadow: var(--glow-success); }
.glow-danger { box-shadow: var(--glow-danger); }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--glass-border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.15); }

/* Animations */
@keyframes pulse-glow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.animate-pulse-glow {
  animation: pulse-glow 2s ease-in-out infinite;
}

