interface TodoItem {
  id: string;
  text: string;
  checked?: boolean;
  priority?: string;
}

interface TodoListProps {
  title?: string;
  items?: TodoItem[];
  onRespond: (data: Record<string, unknown>) => void;
}

export function TodoList({ title, items = [], onRespond }: TodoListProps) {
  const handleToggle = (item: TodoItem) => {
    onRespond({ action: 'toggle', itemId: item.id, checked: !item.checked });
  };

  return (
    <div className="bg-gray-900/50 backdrop-blur-md rounded-2xl border border-gray-800 p-4">
      {title && (
        <h2 className="font-mono text-sm text-cyan-400 mb-3">{title}</h2>
      )}

      <ul className="space-y-1">
        {items.map((item) => (
          <li key={item.id} className="flex items-start gap-3 group">
            <button
              onClick={() => handleToggle(item)}
              className={`
                mt-0.5 w-4 h-4 rounded border flex items-center justify-center shrink-0
                transition-colors
                ${
                  item.checked
                    ? 'bg-cyan-500 border-cyan-500'
                    : 'border-gray-600 hover:border-cyan-500/50'
                }
              `}
            >
              {item.checked && (
                <svg
                  className="w-2.5 h-2.5 text-black"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={3}
                >
                  <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                </svg>
              )}
            </button>

            <span
              className={`text-sm leading-snug ${
                item.checked
                  ? 'line-through text-gray-600'
                  : 'text-gray-200'
              }`}
            >
              {item.text}
            </span>

            {item.priority && (
              <span className="ml-auto text-[10px] font-mono text-gray-500 shrink-0">
                {item.priority}
              </span>
            )}
          </li>
        ))}
      </ul>

      {items.length === 0 && (
        <p className="text-xs text-gray-600 font-mono text-center py-4">
          No items
        </p>
      )}
    </div>
  );
}

import ReactMarkdown from 'react-markdown';

interface MarkdownCardProps {
  content?: string;
  title?: string;
  onRespond: (data: Record<string, unknown>) => void;
}

export function MarkdownCard({ content, title }: MarkdownCardProps) {
  return (
    <div className="bg-gray-900/50 backdrop-blur-md rounded-2xl border border-gray-800 p-4">
      {title && (
        <h2 className="font-mono text-sm text-cyan-400 mb-3">{title}</h2>
      )}

      {content ? (
        <div
          className="
            prose prose-invert prose-sm max-w-none
            prose-headings:text-gray-200 prose-headings:font-mono
            prose-code:text-cyan-400 prose-code:bg-gray-800/60 prose-code:px-1 prose-code:rounded
            prose-pre:bg-gray-900 prose-pre:border prose-pre:border-gray-800
            prose-a:text-cyan-400 prose-a:no-underline hover:prose-a:underline
            prose-li:text-gray-300
            prose-p:text-gray-300
          "
        >
          <ReactMarkdown>{content}</ReactMarkdown>
        </div>
      ) : (
        <p className="text-xs text-gray-600 font-mono">No content</p>
      )}
    </div>
  );
}

